"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('All tables:', tables.map(t => t.name));
const cartTables = tables.filter(t => t.name.toLowerCase().includes('cart'));
console.log('Cart tables:', cartTables);
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Schema
const cartCols = db.pragma('table_info(carts)');
console.log('carts columns:', cartCols.map(c => c.name + ' (' + c.type + ')').join(', '));
const ciCols = db.pragma('table_info(cart_items)');
console.log('cart_items columns:', ciCols.map(c => c.name + ' (' + c.type + ')').join(', '));

// All carts
const carts = db.prepare('SELECT * FROM carts').all();
console.log('\nAll carts:');
carts.forEach(c => console.log(' ', JSON.stringify(c)));

// All cart items
const items = db.prepare('SELECT * FROM cart_items').all();
console.log('\nAll cart_items:');
items.forEach(i => console.log(' ', JSON.stringify(i)));
"

