node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Remove CI-0005 from cart_items
db.prepare('DELETE FROM cart_items WHERE cart_item_id = ?').run('CI-0005');

// Update the cart: remove CI-0005 from item_ids_json, recalculate subtotal/total
// Remaining items: CI-0006 (PROD-93D48F, qty 3, $89 each = $267) + CI-0007 (PROD-B7C77D, qty 2, $72 each = $144) = $411
const newSubtotal = 267 + 144; // 411
db.prepare(\`
  UPDATE carts 
  SET item_ids_json = ?,
      subtotal = ?,
      total = ?
  WHERE cart_id = ?
\`).run(
  JSON.stringify(['CI-0006', 'CI-0007']),
  newSubtotal,
  newSubtotal, // shipping_cost is 0
  'CART-user_58b0a2d6'
);

// Verify
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_58b0a2d6');
console.log('Updated cart:', JSON.stringify(cart, null, 2));
const items = db.prepare('SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?').all('CART-user_58b0a2d6');
console.log('Remaining items:');
items.forEach(i => console.log(' ', i.cart_item_id, i.name, 'qty:', i.quantity, 'price:', i.price));
db.close();
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update CI-0006 quantity from 3 to 2
db.prepare('UPDATE cart_items SET quantity = ? WHERE cart_item_id = ?').run(2, 'CI-0006');

// Recalculate: CI-0006 (qty 2 × $89 = $178) + CI-0007 (qty 2 × $72 = $144) = $322
const newSubtotal = 178 + 144; // 322
db.prepare('UPDATE carts SET subtotal = ?, total = ? WHERE cart_id = ?').run(newSubtotal, newSubtotal, 'CART-user_58b0a2d6');

// Verify
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_58b0a2d6');
console.log('Updated cart:', JSON.stringify(cart, null, 2));
const items = db.prepare('SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?').all('CART-user_58b0a2d6');
console.log('Remaining items:');
items.forEach(i => console.log(' ', i.cart_item_id, i.name, 'qty:', i.quantity, 'unit price:', i.price, 'line total:', i.quantity * i.price));
"

