const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check orders table schema
const cols = db.pragma('table_info(orders)');
console.log('orders columns:', cols.map(c => c.name + ' (' + c.type + ')').join(', '));

// Check order_items schema
const oiCols = db.pragma('table_info(order_items)');
console.log('order_items columns:', oiCols.map(c => c.name + ' (' + c.type + ')').join(', '));

// Check order_payments schema
const opCols = db.pragma('table_info(order_payments)');
console.log('order_payments columns:', opCols.map(c => c.name + ' (' + c.type + ')').join(', '));

// Check a sample order for format reference
const sample = db.prepare('SELECT * FROM orders LIMIT 1').get();
console.log('\nSample order:', JSON.stringify(sample, null, 2));

const sampleItems = db.prepare('SELECT * FROM order_items LIMIT 2').all();
console.log('\nSample order_items:', JSON.stringify(sampleItems, null, 2));

const samplePayments = db.prepare('SELECT * FROM order_payments LIMIT 1').all();
console.log('\nSample order_payments:', JSON.stringify(samplePayments, null, 2));

// Get the user's info for address/payment
const user = db.prepare('SELECT * FROM users WHERE user_id = ?').get('user_58b0a2d6');
console.log('\nUser:', JSON.stringify(user, null, 2));

// Check existing order count for ID generation
const orderCount = db.prepare('SELECT COUNT(*) as cnt FROM orders').get();
console.log('\nTotal orders:', orderCount.cnt);

// Get max order_id
const maxOrder = db.prepare(\"SELECT order_id FROM orders ORDER BY order_id DESC LIMIT 1\").get();
console.log('Max order_id:', maxOrder);
"

node -e "
const crypto = require('crypto');
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Generate a unique order ID
const orderId = 'ORD-' + crypto.randomBytes(3).toString('hex').toUpperCase().slice(0, 6);
const now = new Date().toISOString().slice(0, 10); // date only
const nowFull = new Date().toISOString().replace('T', ' ').slice(0, 19);

const userId = 'user_58b0a2d6';
const paymentMethodId = 'cc_dacf96ec';
const addressJson = '{\"address1\":\"156 Main Street\",\"address2\":\"\",\"city\":\"Portland\",\"state\":\"OR\",\"zip\":\"97201\",\"country\":\"USA\"}';

// Insert order
db.prepare(\`
  INSERT INTO orders (
    order_id, customer_id, order_date, status, shipping_status,
    shipping_method, shipping_cost, tracking_number, delivery_date,
    delivery_promised_date, signature_required, signature_on_file,
    payment_method, payment_details_json, subtotal, discount_code,
    discount_amount, total_paid, is_gift, gift_sender, source_skill,
    address_json
  ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
\`).run(
  orderId, userId, now, 'pending', 'pending',
  'standard', 0, '', null,
  '', 0, null,
  paymentMethodId, JSON.stringify({credit_card: 322}), 322, null,
  0, 322, 0, null, 'state-shopping',
  addressJson
);

// Insert order items
// CI-0006: RidgeLine Fleece Zip Hoodie (PROD-93D48F), qty 2, $89
const itemId1 = 'ITEM-' + crypto.randomBytes(3).toString('hex').toUpperCase().slice(0, 6);
db.prepare(\`
  INSERT INTO order_items (
    oi_id, order_id, product_id, item_id, name, quantity, unit_price,
    options, item_status, return_label_issued, goodwill_credit, store_credit_only
  ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
\`).run(itemId1, orderId, 'PROD-93D48F', null, 'RidgeLine Fleece Zip Hoodie', 2, 89, '{}', 'pending', 0, 0, 0);

// CI-0007: Metro Stretch Chino Pants (PROD-B7C77D), qty 2, $72
const itemId2 = 'ITEM-' + crypto.randomBytes(3).toString('hex').toUpperCase().slice(0, 6);
db.prepare(\`
  INSERT INTO order_items (
    oi_id, order_id, product_id, item_id, name, quantity, unit_price,
    options, item_status, return_label_issued, goodwill_credit, store_credit_only
  ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
\`).run(itemId2, orderId, 'PROD-B7C77D', null, 'Metro Stretch Chino Pants', 2, 72, '{}', 'pending', 0, 0, 0);

// Insert payment record
db.prepare(\`
  INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id, created_at)
  VALUES (?, ?, ?, ?, ?)
\`).run(orderId, 'payment', 322, paymentMethodId, nowFull);

// Clear the cart
db.prepare('DELETE FROM cart_items WHERE cart_id = ?').run('CART-user_58b0a2d6');
db.prepare(\`
  UPDATE carts SET subtotal = 0, total = 0, shipping_option = null, shipping_cost = 0,
  item_ids_json = '[]' WHERE cart_id = ?
\`).run('CART-user_58b0a2d6');

// Verify
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(orderId);
console.log('New order:', JSON.stringify(order, null, 2));

const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(orderId);
console.log('Order items:', JSON.stringify(items, null, 2));

const payment = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(orderId);
console.log('Payment:', JSON.stringify(payment, null, 2));

const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_58b0a2d6');
console.log('Cart after clearing:', JSON.stringify(cart, null, 2));

db.close();
"
